const items = $input.all();
return items.map(item => {
  const data = item.json;
  const headers = data.headers || {};
  const subject = (headers.subject || data.subject || '').toString();
  const from = (headers.from || data.from || '').toString();
  const to = (headers.to || data.to || '').toString();
  const text = (data.text || data.textPlain || data.html || '').toString();

  return {
    json: {
      messageId: headers['message-id'] || data.messageId || '',
      receivedAt: data.date || new Date().toISOString(),
      subject: subject.trim(),
      from: from.trim(),
      to: to.trim(),
      bodyPreview: text.replace(/\s+/g, ' ').slice(0, 4000)
    }
  };
});

// Deterministic pre-classification: spart Claude-Tokens, wenn der Fall eindeutig ist.
const item = $input.first();
const j = item.json;
const subject = (j.subject || '').toLowerCase();
const body = (j.bodyPreview || '').toLowerCase();
const from = (j.from || '').toLowerCase();
const text = subject + ' ' + body;

const bookingDomains = [
  'booking.com', 'lodgify.com', 'airbnb.com', 'expedia.com',
  'agoda.com', 'vrbo.com', 'hrs.de', 'fewo-direkt.de', 'tripadvisor.com'
];
const isBookingSender = bookingDomains.some(d => from.includes(d));

// Banking/Rechnungen sehen oberflächlich nach Buchung aus, sind es aber nicht.
const bankingKeywords = ['abgebucht', 'lastschrift', 'sepa-mandat', 'rechnung im anhang', 'mahnung', 'zahlungserinnerung'];
const isBanking = bankingKeywords.some(k => text.includes(k));

// Buchungs-Keywords (Treffer im Body)
const bookingBodyKeywords = [
  'gebucht', 'gebuchte', 'gebuchten', 'gebuchter', 'gebuchtes',
  'ausgebucht', 'überbucht', 'umgebucht', 'vorgebucht', 'doppelgebucht',
  'buchung', 'buchungen', 'buchungsbestätigung', 'buchungsnummer', 'buchungscode',
  'reservierung', 'reservierungs', 'reserviert',
  'booking confirmation', 'reservation confirmation', 'new booking', 'new reservation',
  'check-in', 'anreise', 'arrival'
];
// Buchungs-Indizien im Subject (mind. eines muss zutreffen)
const bookingSubjectHints = [
  'buchung', 'booking', 'reservation', 'reservierung',
  'bestätig', 'confirm', 'gebucht', 'check-in', 'anreise'
];

const hasBodyKeyword = bookingBodyKeywords.some(k => text.includes(k));
const hasSubjectHint = bookingSubjectHints.some(k => subject.includes(k));

// Bewertungs-Keywords
const reviewKeywords = ['bewertung abgeben', 'bewerten sie', 'bewertung hinterlassen', 'bewertung erhalten', 'review request', 'leave a review', 'rate your stay', 'sterne'];
const hasReviewKeyword = reviewKeywords.some(k => text.includes(k));

// Anfrage-Keywords (Form-Submissions / Anfragen über Website)
const inquiryKeywords = ['anfrage', 'verfügbarkeit', 'verfügbar', 'preis', 'angebot', 'frage zu', 'kann ich', 'wäre möglich', 'inquiry', 'availability'];
const hasInquiryKeyword = inquiryKeywords.some(k => text.includes(k));
const inquirySubjectHints = ['anfrage', 'verfügbarkeit', 'inquiry', 'request'];
const hasInquirySubject = inquirySubjectHints.some(k => subject.includes(k));

let preClassified = false;
let category = null;
let reason = '';

if (!isBanking && isBookingSender) {
  preClassified = true;
  category = 'BUCHUNG';
  reason = 'sender domain match (' + from.replace(/.*@/, '') + ')';
} else if (!isBanking && hasBodyKeyword && hasSubjectHint) {
  preClassified = true;
  category = 'BUCHUNG';
  reason = 'booking keywords in subject + body';
} else if (hasReviewKeyword) {
  preClassified = true;
  category = 'BEWERTUNG';
  reason = 'review keyword match';
} else if (hasInquirySubject && hasInquiryKeyword) {
  preClassified = true;
  category = 'ANFRAGE';
  reason = 'inquiry keywords in subject + body';
}

return [{
  json: {
    ...j,
    preClassified,
    preCategory: category,
    preReason: reason
  }
}];

const items = $input.all();
return items.map(item => {
  const j = item.json;
  return {
    json: {
      ...j,
      classification: {
        category: j.preCategory,
        confidence: 1,
        summary: 'Automatisch klassifiziert (' + j.preReason + ').',
        action_required: j.preCategory !== 'SONSTIGES',
        suggested_reply: null
      }
    }
  };
});

values.content:
=Du bist ein Klassifikator für eingehende E-Mails einer Ferienwohnungs-Vermietung (Move-in2Stay).

Klassifiziere die folgende E-Mail in GENAU eine Kategorie:
- BUCHUNG: Konkrete Buchungsbestätigung oder Reservierung (z. B. von Booking.com, Lodgify, Airbnb).
- ANFRAGE: Anfrage nach Verfügbarkeit, Preisen, Langzeit, Gruppen, etc.
- BEWERTUNG: Gast-Bewertung oder Aufforderung zur Bewertung.
- SONSTIGES: Spam, Newsletter, Rechnungen, alles andere.

Antworte ausschließlich als JSON-Objekt mit folgendem Schema:
{
  "category": "BUCHUNG" | "ANFRAGE" | "BEWERTUNG" | "SONSTIGES",
  "confidence": number (0-1),
  "summary": string (max 280 Zeichen, Deutsch, sachlich),
  "action_required": boolean,
  "suggested_reply": string | null
}

E-MAIL:
Von: {{ $json.from }}
An: {{ $json.to }}
Betreff: {{ $json.subject }}
Empfangen: {{ $json.receivedAt }}

{{ $json.bodyPreview }}

