const items = $input.all();
return items.map(item => {
  const original = item.json.original || item.json;
  let parsed = { category: 'SONSTIGES', confidence: 0, summary: '', action_required: false, suggested_reply: null };
  const raw = item.json.content?.[0]?.text || item.json.text || item.json.message || '';
  try {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) parsed = { ...parsed, ...JSON.parse(match[0]) };
  } catch (e) {
    parsed.summary = 'Klassifikation fehlgeschlagen: ' + (e.message || 'unknown');
  }
  return {
    json: {
      ...original,
      classification: parsed
    }
  };
});
